head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods20001";
scwin.editor = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_lawTitle", fn: function () { return String(String((dma_pageContext.get("relLawDtlNm2") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldods20001: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.editor =new Dext5editor("dext5editor1"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldods20001' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods20001.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_searchLawList_oncellclick
 * @description grd_searchLawList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_searchLawList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_searchLawList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_searchLawList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.search_detail(r["relLawDtlNo"], r["relLawDtlNm"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_searchLawList.oncellclick' });
    }
};

/**
 * @method
 * @name input_33_onclick
 * @description 「미리보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_33_onclick = function(e){
    try {
        scwin.openRelLaw()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20001.input_33_onclick' }); }
};

/**
 * @method
 * @name input_34_onclick
 * @description 「등록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_34_onclick = function(e){
    try {
        scwin.regRelLaw()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods20001.input_34_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search_detail
 * @description search detail 처리
 * @param {*} relLawDtlNo relLawDtlNo
 * @param {String} relLawDtlNm relLawDtlNm
 * @returns {void}
 * @hidden N
 */
scwin.search_detail = function (relLawDtlNo, relLawDtlNm) {
    const curRelLawDtlNo = $('#relLawDtlNo').val();
    if (curRelLawDtlNo === relLawDtlNo) {
        return;
    }
    $c.util.getComponent('dma_hiddenStore').set('method', "lawMain");
    $('#relLawDtlNo').val(relLawDtlNo);
    $c.util.getComponent('relLawDtlNm').setValue(relLawDtlNm);
    $('#headerKeywrdForm')[0].submit();
    blockLoading();
};

/**
 * @method
 * @name regRelLaw
 * @description reg Rel Law 처리
 * @returns {void}
 * @hidden N
 */
scwin.regRelLaw = function () {
    const a = DEXT5.getBodyValue("dext5editor1");
    $c.util.getComponent('dma_hiddenStore').set('relLawDtlContn', a);
    $c.util.getComponent('dma_hiddenStore').set('method', "updateRelLawDtl");
    $('#headerKeywrdForm')[0].submit();
};

/**
 * @method
 * @name dext_editor_loaded_event
 * @description dext editor loaded event 처리
 * @param {*} editor editor
 * @returns {void}
 * @hidden N
 */
scwin.dext_editor_loaded_event = function (editor) {
    DEXT5.setBodyValue(dma_hiddenStore.get("relLawDtlContn"), editor.ID);
};

/**
 * @method
 * @name searchRelLaw
 * @description search Rel Law 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchRelLaw = async function () {
    const formCd = $('#roomNo option:selected').val();
    if (formCd.length === 0) {
        await $c.win.alert("법규전문을 선택해 주세요.");
        return;
    }
    scwin.searchList("1");
};

/**
 * @method
 * @name searchRelLaw2
 * @description search Rel Law2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchRelLaw2 = async function () {
    const formCd = dma_hiddenStore.get("lawNm");
    if (formCd.length === 0) {
        await $c.win.alert("단위조항명을 입력해 주세요.");
        return;
    }
    scwin.searchList("2");
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @param {*} div div
 * @returns {void}
 * @hidden N
 */
scwin.searchList = function (div) {
    $c.util.getComponent('dma_hiddenStore').set('method', "lawMain");
    if (div === "1") {
        $c.util.getComponent('dma_hiddenStore').set('lawNm', "");
    } else {
        if (div === "2") {
            $c.util.getComponent('dma_hiddenStore').set('roomNo', "");
        }
    }
    $('#headerKeywrdForm')[0].submit();
    blockLoading();
};

/**
 * @method
 * @name openRelLaw
 * @description open Rel Law 처리
 * @returns {void}
 * @hidden N
 */
scwin.openRelLaw = function () {
    $c.win.openPopup("", { id: "관련법규", scrollbars: true, width: "1120", height: "800", resizable: true, type: "pageFramePopup" }, {});
    let form = create_form('relLawForm', 'POST', '/insert/findRelLaw.do', "관련법규");
    form = add_input(form, 'relLawDtlNo', $('#relLawDtlNo').val());
    form = add_input(form, 'method', "findRelLawList");
    document.body.insertBefore(form, null);
    form.submit();
};
